  "toolCatalog": {
    "physical-input": {
      "name": "Input device",
      "help": "Sound from a microphone, line input, or virtual cable (for example CABLE Output). Choose the device in Properties."
    },
    "test-signal": {
      "name": "Test Signal",
      "help": "A steady tone for checking a route without speaking. Press Play tone on its card to start it."
    },
    "audio-file": {
      "name": "Audio file",
      "help": "Play a WAV or MP3 through the graph. Select media in the node properties."
    },
    "soundboard": {
      "name": "Soundboard",
      "help": "Up to nine sounds on buttons. Trigger them here, from the API or from a Stream Deck."
    },
    "endpoint-loopback": {
      "name": "Endpoint loopback",
      "help": "Select an exact active render endpoint in Endpoint binding"
    },
    "virtual-render-source": {
      "name": "Cable input",
      "help": "Sound that another app plays into an AudioRouter cable (for example a game set to output to Cable A Input). Choose the cable in Properties."
    },
    "physical-output": {
      "name": "Output device",
      "help": "Send sound to speakers, headphones, or a virtual cable (for example CABLE Input) that another app uses as its input. Choose the device in Properties."
    },
    "network-receive": {
      "name": "Network Receive",
      "help": "Play audio streamed by AudioRouter on another computer on your network, for example game audio from a gaming PC. Enter that computer's IP address."
    },
    "network-send": {
      "name": "Network Send",
      "help": "Stream audio to AudioRouter on another computer on your network, for example from a gaming PC to a streaming PC. Enter the receiving computer's IP address."
    },
    "virtual-capture-sink": {
      "name": "Cable output",
      "help": "Send sound into an AudioRouter cable that another app records from (for example Discord's microphone set to Cable B Output). Choose the cable in Properties."
    },
    "volume": {
      "name": "Volume",
      "help": "Set one source's level in percent (0–200 %) before it reaches a Mixer."
    },
    "gain": {
      "name": "Gain",
      "help": "Make the sound louder or quieter, in decibels."
    },
    "bass-treble": {
      "name": "Bass & Treble",
      "help": "Shape voice warmth and brightness by up to 12 dB. Adjustable shelf frequencies let you affect more or less of your voice."
    },
    "dehum": {
      "name": "Dehum",
      "help": "Remove low-frequency electrical hum at 50 or 60 Hz and its harmonics."
    },
    "declick": {
      "name": "Declick",
      "help": "Repair clicks, pops, and crackle. A lower threshold repairs more but may alter sharp sounds."
    },
    "denoise": {
      "name": "Denoise",
      "help": "Learn a steady noise (fan, hiss, hum) while nothing else plays, then remove it."
    },
    "speech-denoise": {
      "name": "Speech Denoise",
      "help": "Automatically reduce background noise around speech. Runs locally with a spectral method, not a machine-learning model."
    },
    "spectral-gate": {
      "name": "Spectral Gate",
      "help": "Learn the noise at every frequency, then block whatever stays below it, like ReaFIR's gate. Shows a live spectrum."
    },
    "fir-filter": {
      "name": "FIR Filter",
      "help": "Give your sound the character of a room, speaker or mic from its impulse response (WAV or MP3, up to 2 s). Wet mix blends it with the original."
    },
    "time-shift": {
      "name": "Time Shift",
      "help": "A DVR for live audio: pause, jump back or forward 10 s, and return to live. Keeps up to 120 s."
    },
    "mixer": {
      "name": "Mixer",
      "help": "Combine several sources into one, with a volume for each input."
    },
    "duck": {
      "name": "Duck",
      "help": "Turn this audio down automatically while another source is loud (for example game sound while you talk), or in chosen Siege phases with Stats.cc. Choose the trigger in Properties."
    },
    "input-switch": {
      "name": "Input Switch",
      "help": "Pass either input A or input B. Switching crossfades over 0.5 s (Shift-click for 2 s)."
    },
    "output-switch": {
      "name": "Output Switch",
      "help": "Send one signal to output A or B, such as headphones or OBS. Only the selected side receives audio; switch with Properties or Stream Deck."
    },
    "recorder": {
      "name": "Recorder",
      "help": "Record the sound passing through this point to a file on this PC."
    },
    "mute": {
      "name": "Mute",
      "help": "Silence this part of the route without disconnecting anything."
    },
    "meter": {
      "name": "Meter",
      "help": "Show the level of the sound at this point, to check it is neither too quiet nor clipping."
    },
    "parametric-eq": {
      "name": "Advanced EQ",
      "help": "Place up to 16 EQ points with peaking, shelves, low/high/band pass, all pass, or notch filters."
    },
    "compressor": {
      "name": "Compressor",
      "help": "Even out loud and quiet moments so a voice sits at a steady level."
    },
    "gate": {
      "name": "Gate",
      "help": "Silence quiet background noise between words; opens when you speak."
    },
    "limiter": {
      "name": "Limiter",
      "help": "Hold peaks under a ceiling so sudden loud sounds never clip or distort."
    },
    "delay": {
      "name": "Sync (delay)",
      "help": "Delay audio by 0–1000 ms to line it up with video or another source. Chain several for longer delays."
    },
    "graphic-eq": {
      "name": "Graphic EQ",
      "help": "Boost or cut ten fixed frequency bands, from deep bass (31.5 Hz) to air (16 kHz)."
    },
    "pitch": {
      "name": "Pitch shift",
      "help": "Shift the pitch up or down without changing the speed."
    },
    "fun-voice-changer": {
      "name": "Fun Voice Changer",
      "help": "Playful voice presets you can tweak: pitch correct, deep, chipmunk, robot, monster, radio, whisper and more. Adds 21 ms delay; output is mono."
    }
  },
